import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.AwardAchievement{AchievementID: 300}
POSITIVE = bytes.fromhex("2c010000")

# generated by gophertunnel b8bd735:
# &packet.AwardAchievement{AchievementID: -1}
NEGATIVE = bytes.fromhex("ffffffff")

GOLDENS = [
    pytest.param(v2225.AwardAchievementPacket(achievement_id=300), POSITIVE, id="positive"),
    pytest.param(v2225.AwardAchievementPacket(achievement_id=-1), NEGATIVE, id="negative-is-a-signed-fixed-int32"),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_award_achievement_is_packet_309(version):
    assert version.packets[309] is version.AwardAchievementPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_award_achievement_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_award_achievement_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
